"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["28911"],{86471(e){e.exports=JSON.parse('{"id":"FIN-244","slug":"fixed-income-security","term":"Fixed-Income Security","also_known_as":[],"difficulty":"Beginner","definition":"A fixed-income security is an investment that pays a set amount of interest or income at regular intervals and returns the principal at maturity, such as a bond.","explanation":["The name comes from the predictable payments these securities make. The investor knows in advance how much interest will be paid and when, as long as the issuer does not default.","Fixed-income securities include government bonds, corporate bonds, municipal bonds, treasury bills, certificates of deposit and some types of preferred stock. Some pay interest at a fixed rate; others, despite the name, pay a rate that adjusts with a benchmark.","Investors use fixed-income securities to earn steady income, to preserve capital and to reduce the overall volatility of a portfolio, since their prices generally move less than share prices.","For example, a retiree might hold a mix of government and corporate bonds that pay interest every six months to provide predictable income.","Fixed-income securities still carry risks. Interest rate risk means prices fall when market rates rise. Credit risk is the chance the issuer cannot pay. Inflation risk is the possibility that rising prices erode the real value of the fixed payments."],"note":"","total":1725,"prev":{"slug":"fixed-exchange-rate","term":"Fixed Exchange Rate"},"next":{"slug":"fixed-rate","term":"Fixed Rate"}}')}}]);